pub fn primitive_fact_bundle_list_head_substrate(
    bundles: Rc<Vec<Rc<PrimitiveFactBundle>>>,
) -> Rc<Node> {
    match (*fold_list(
        bundles.clone(),
        Rc::new(PrimitiveBundleSubstrateHead::PrimitiveBundleSubstrateHeadMissing),
        |acc, bundle| match (*acc.clone()).clone() {
            PrimitiveBundleSubstrateHead::PrimitiveBundleSubstrateHeadFound {
                substrate: _,
                ..
            } => acc.clone(),
            PrimitiveBundleSubstrateHead::PrimitiveBundleSubstrateHeadMissing => Rc::new(
                PrimitiveBundleSubstrateHead::PrimitiveBundleSubstrateHeadFound {
                    substrate: primitive_fact_bundle_substrate(bundle.clone()),
                },
            ),
        },
    ))
    .clone()
    {
        PrimitiveBundleSubstrateHead::PrimitiveBundleSubstrateHeadFound {
            substrate: node, ..
        } => node.clone(),
        PrimitiveBundleSubstrateHead::PrimitiveBundleSubstrateHeadMissing => {
            model_core_empty_conj_node()
        }
    }
}

